import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      userList: [],
      searchTerm: "",

      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",

      loading: true,
      authenticated: false,
    };

    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);

    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getUsers();
      }
    );
  }

  // =========================
  // دریافت کاربران
  // =========================
  getUsers = () => {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",

      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("USERS API:", data);

        /*
         * API:
         *
         * {
         *   status: "1",
         *   message: "لیست کاربران",
         *   user: [...]
         * }
         */

        if (String(data.status) !== "1") {
          this.setState({
            userList: [],
            loading: false,
          });

          return;
        }

        const users = Array.isArray(data.user) ? data.user : [];

        console.log("USER LIST:", users);

        this.setState({
          userList: users,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          userList: [],
          loading: false,
        });
      });
  };

  // =========================
  // سرچ
  // =========================
  handleSearchChange(e) {
    this.setState({
      searchTerm: e.target.value,
    });
  }

  // =========================
  // فیلتر
  // فعلاً غیرفعال
  // =========================
  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    // فعلاً فیلتر واقعی انجام نمی‌شود
    this.closeFilter();
  }

  // =========================
  // حذف کاربر
  // POST /delete
  // =========================
  handleDelete(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/delete`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("DELETE USER:", data);

        if (String(data.status) === "1") {
          this.setState((prevState) => ({
            userList: prevState.userList.filter(
              (user) => user.id !== id
            ),
          }));
        }
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
      });
  }

  // =========================
  // تغییر وضعیت
  // POST /active
  // =========================
  handleToggleStatus(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("ACTIVE USER:", data);

        if (String(data.status) === "1") {
          /*
           * بعد از موفقیت API دوباره لیست را می‌گیریم
           * تا وضعیت دقیق از سرور بیاید.
           */
          this.getUsers();
        }
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
      });
  }

  // =========================
  // جزئیات
  // =========================
  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      userList,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت تعمیرکاران...
        </div>
      );
    }

    /*
     * فقط سرچ اسم انجام می‌شود.
     *
     * فیلتر استان / شهر / تخصص
     * فعلاً هیچ تأثیری روی لیست ندارد.
     */

    const search = searchTerm.trim().toLowerCase();

    const displayedUsers = userList.filter((user) => {
      const fullName = `${user.name || ""} ${user.family || ""}`
        .trim()
        .toLowerCase();

      return fullName.includes(search);
    });

    return (
      <div dir="rtl">
        <div className="container px-3 pt-3">

          {/* ================= سرچ ================= */}
          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">
            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />
          </div>

          {/* ================= فیلتر ================= */}
          <div className="d-flex justify-content-end mb-3">
            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>
          </div>

          {/* ================= عنوان ================= */}
          <div className="bg-light text-center rounded-3 py-3 mb-1">
            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>
          </div>

          {/* ================= لیست ================= */}
          <div>
            {displayedUsers.map((user) => (
              <TechnicianItem
                key={user.id}
                technician={user}
                onDelete={this.handleDelete}
                onToggleStatus={this.handleToggleStatus}
                onDetails={this.handleDetails}
              />
            ))}

            {displayedUsers.length === 0 && (
              <div className="text-center text-muted py-5">
                موردی یافت نشد
              </div>
            )}
          </div>
        </div>

        {/* ================= FilterSheet ================= */}
        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}
          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}
          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }
          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }
          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />
      </div>
    );
  }
}

export default TechniciansPage;
